import os
import time
from typing import Any, Dict, Optional

import msal
from flask import Flask, jsonify, redirect, request, session, url_for

app = Flask(__name__)
app.secret_key = os.environ.get("FLASK_SECRET_KEY", "change-me")

AZURE_TENANT_ID = os.environ.get("AZURE_TENANT_ID", "common")
AZURE_CLIENT_ID = os.environ.get("AZURE_CLIENT_ID")
AZURE_CLIENT_SECRET = os.environ.get("AZURE_CLIENT_SECRET")
AZURE_REDIRECT_URI = os.environ.get("AZURE_REDIRECT_URI")

if not AZURE_CLIENT_ID:
    raise RuntimeError("AZURE_CLIENT_ID is required")
if not AZURE_CLIENT_SECRET:
    raise RuntimeError("AZURE_CLIENT_SECRET is required")
if not AZURE_REDIRECT_URI:
    AZURE_REDIRECT_URI = "http://localhost:5000/callback"

AUTHORITY = f"https://login.microsoftonline.com/{AZURE_TENANT_ID}"
SCOPES = ["openid", "profile", "email", "offline_access", "User.Read"]


def _build_msal_app() -> msal.ConfidentialClientApplication:
    return msal.ConfidentialClientApplication(
        client_id=AZURE_CLIENT_ID,
        client_credential=AZURE_CLIENT_SECRET,
        authority=AUTHORITY,
    )


@app.route("/login")
def login() -> Any:
    msal_app = _build_msal_app()
    state = os.urandom(16).hex()
    session["auth_state"] = state
    auth_url = msal_app.get_authorization_request_url(
        scopes=SCOPES,
        state=state,
        redirect_uri=AZURE_REDIRECT_URI,
        prompt="select_account",
    )
    return redirect(auth_url)


@app.route("/callback")
def callback() -> Any:
    error = request.args.get("error")
    if error:
        return jsonify(
            {
                "error": error,
                "error_description": request.args.get("error_description"),
                "error_uri": request.args.get("error_uri"),
            }
        ), 400

    code = request.args.get("code")
    state = request.args.get("state")

    if not code:
        return jsonify({"error": "missing_authorization_code"}), 400
    if not state or state != session.get("auth_state"):
        return jsonify({"error": "invalid_state"}), 400

    msal_app = _build_msal_app()
    token_result = msal_app.acquire_token_by_authorization_code(
        code=code,
        scopes=SCOPES,
        redirect_uri=AZURE_REDIRECT_URI,
    )

    if "error" in token_result:
        return jsonify(token_result), 400

    normalized: Dict[str, Any] = {
        "access_token": token_result.get("access_token"),
        "id_token": token_result.get("id_token"),
        "refresh_token": token_result.get("refresh_token"),
        "token_type": token_result.get("token_type"),
        "scope": token_result.get("scope"),
        "expires_in": token_result.get("expires_in"),
        "expires_at": int(time.time()) + int(token_result.get("expires_in", 0)),
        "account": token_result.get("id_token_claims") or token_result.get("account"),
    }
    return jsonify(normalized)


@app.route("/")
def index() -> Any:
    return jsonify(
        {
            "login_url": url_for("login", _external=True),
            "callback_url": url_for("callback", _external=True),
            "authority": AUTHORITY,
            "redirect_uri": AZURE_REDIRECT_URI,
        }
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", "5000")))
